// Web build only: loads the recorded AI answers for a sample file (generated by scripts/record-samples.ts).
import type { Recorded } from "./api.ts";

const files = import.meta.glob<{ default: Recorded }>("./recorded/*.json");

export async function loadRecorded(sample: string): Promise<Recorded | null> {
  const load = files[`./recorded/${sample}.json`];
  return load ? (await load()).default : null;
}
